AssistantMessageToolRequest(name='create', tool_call_id='function-call-54cf2832-9732-4d8d-bc30-dd8d7d4e48b6', arguments={'file_text': 'const { useState } = React;

const QUESTIONS = [
  {
    id: 'q1',
    question: 'Which of the following are statically-typed languages?',
    options: [
      { id: 'q1-o1', label: 'Java', value: 'java' },
      { id: 'q1-o2', label: 'Python', value: 'python' },
      { id: 'q1-o3', label: 'C++', value: 'cpp' },
      { id: 'q1-o4', label: 'JavaScript', value: 'js' }
    ],
    helpText: 'Statically-typed languages perform type checking at compile-time.'
  },
  {
    id: 'q2',
    question: 'Which languages are commonly used for systems programming?',
    options: [
      { id: 'q2-o1', label: 'Rust', value: 'rust' },
      { id: 'q2-o2', label: 'Ruby', value: 'ruby' },
      { id: 'q2-o3', label: 'C', value: 'c' },
      { id: 'q2-o4', label: 'PHP', value: 'php' }
    ]
  },
  {
    id: 'q3',
    question: 'Which of these are functional programming languages (or strongly support functional paradigms)?',
    options: [
      { id: 'q3-o1', label: 'Haskell', value: 'haskell' },
      { id: 'q3-o2', label: 'Elixir', value: 'elixir' },
      { id: 'q3-o3', label: 'Scala', value: 'scala' },
      { id: 'q3-o4', label: 'C', value: 'c' }
    ]
  }
];

const CheckboxOption = ({ id, label, value, name, checked, onChange }) => (
  <div className="option-item">
    <input
      type="checkbox"
      id={id}
      name={name}
      value={value}
      checked={checked}
      onChange={(e) => onChange(value, e.target.checked)}
    />
    <label htmlFor={id}>{label}</label>
  </div>
);

const Question = ({ config, answers, onAnswerChange }) => {
  const { id, question, options, helpText } = config;
  const helpId = helpText ? `${id}-help` : null;

  return (
    <div className="form-field">
      <fieldset aria-describedby={helpId}>
        <legend>{question}</legend>
        {helpText && (
          <p id={helpId} className="help-text">
            {helpText}
          </p>
        )}
        <div className="options-group">
          {options.map((option) => (
            <CheckboxOption
              key={option.id}
              id={option.id}
              label={option.label}
              value={option.value}
              name={id}
              checked={answers.includes(option.value)}
              onChange={onAnswerChange}
            />
          ))}
        </div>
      </fieldset>
    </div>
  );
};

const Quiz = () => {
  const [answers, setAnswers] = useState({
    q1: [],
    q2: [],
    q3: []
  });
  const [submitted, setSubmitted] = useState(false);

  const handleAnswerChange = (questionId, value, isChecked) => {
    setAnswers((prev) => {
      const currentAnswers = prev[questionId];
      if (isChecked) {
        return { ...prev, [questionId]: [...currentAnswers, value] };
      } else {
        return { ...prev, [questionId]: currentAnswers.filter((v) => v !== value) };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <main className="quiz-container">
      <h1>Computer Languages Quiz</h1>
      <form onSubmit={handleSubmit} noValidate>
        {QUESTIONS.map((q) => (
          <Question
            key={q.id}
            config={q}
            answers={answers[q.id]}
            onAnswerChange={(value, isChecked) => handleAnswerChange(q.id, value, isChecked)}
          />
        ))}
        <button type="submit" className="submit-button">
          Submit Quiz
        </button>
      </form>
      {submitted && (
        <div className="results" aria-live="polite">
          <h2>Quiz Submitted!</h2>
          <p>Thank you for participating.</p>
          <p>Your answers: {Object.values(answers).flat().join(', ') || 'None selected'}</p>
        </div>
      )}
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
